<?php $pageTitle='Activity logs'; $activePage='activity-logs'; require_once __DIR__.'/includes/header.php'; $logs=$pdo->query("SELECT a.*,u.name FROM activity_logs a LEFT JOIN users u ON u.id=a.user_id ORDER BY a.created_at DESC LIMIT 40")->fetchAll(); ?><div class="mb-4"><span class="section-kicker">Audit trail</span><h2 class="mt-2">Activity logs</h2><p class="text-muted mb-0">A shared record of the changes that matter.</p></div><div class="table-shell"><div class="table-responsive"><table class="table"><thead><tr><th>Action</th><th>User</th><th>Record</th><th>Time</th><th>IP address</th></tr></thead><tbody><?php foreach($logs as $log): ?><tr><td><span class="table-title"><?= e($log['action']) ?></span></td><td><?= e($log['name']??'System') ?></td><td><?= e($log['entity_type']) ?> <?= $log['entity_id'] ? '#'.e((string)$log['entity_id']) : '' ?></td><td><?= e(date('M d, Y H:i',strtotime($log['created_at']))) ?></td><td><?= e($log['ip_address']??'n/a') ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require_once __DIR__.'/includes/footer.php'; ?>
